<?php require_once __DIR__.'/../admin_catalog.php';require __DIR__.'/../staff_header.php';$roomStateLabels=['ready'=>'Sẵn sàng','dirty'=>'Chờ dọn','maintenance'=>'Bảo trì']; ?>
<section class="admin-catalog" aria-label="Danh mục phòng thực tế">
    <?php catalog_toolbar('Tìm phòng',count($rooms),'Nhập số phòng hoặc tên loại phòng…','#room-create',false,['categories'=>array_map(static fn($type)=>[$type['id'],$type['name']],$types)]); ?>
    <div class="table-wrap catalog-table-scroll"><table class="catalog-table"><thead><tr><th>Số phòng</th><th>Loại phòng</th><th>Tình trạng</th><th>Hoạt động</th><th class="catalog-action-cell">Hành động</th></tr></thead><tbody>
    <?php foreach($rooms as $room):$roomId=(int)$room['id']; ?>
        <tr data-catalog-row data-search="<?= e($room['number'].' '.$room['room_name']) ?>" data-status="<?= (int)$room['active']?e($room['housekeeping']):'inactive' ?>" data-category="<?= (int)$room['room_type_id'] ?>"><td><span class="catalog-name">Phòng <?= e($room['number']) ?></span></td><td><?= e($room['room_name']) ?></td><td><span class="catalog-status <?= $room['housekeeping']==='ready'?'is-active':($room['housekeeping']==='dirty'?'is-pending':'is-inactive') ?>"><?= e($roomStateLabels[$room['housekeeping']]) ?></span></td><td><?php catalog_status((int)$room['active']?'Đang sử dụng':'Ngừng sử dụng',(bool)$room['active']); ?></td><td><div class="catalog-row-actions"><?php catalog_action('eye','Xem phòng '.$room['number'],'#room-view-'.$roomId);catalog_action('edit','Sửa phòng '.$room['number'],'#room-edit-'.$roomId);catalog_action((int)$room['active']?'trash':'power',(int)$room['active']?'Ngừng sử dụng phòng '.$room['number']:'Mở lại phòng '.$room['number'],'#room-status-'.$roomId,(bool)$room['active']); ?></div></td></tr>
    <?php endforeach;catalog_empty(5,(bool)$rooms); ?>
    </tbody></table></div>
    <p class="catalog-note">Phòng có lịch sử được ngừng sử dụng thay vì xóa. Hệ thống vẫn kiểm tra khách đang ở và số phòng đã cam kết trước khi lưu.</p>
    <?php foreach($rooms as $room):$roomId=(int)$room['id'];$target=(int)$room['active']?0:1; ?>
        <?php catalog_dialog_start('room-view-'.$roomId,'Phòng '.$room['number'],$room['room_name']);catalog_details(['Số phòng'=>$room['number'],'Loại phòng'=>$room['room_name'],'Tình trạng'=>$roomStateLabels[$room['housekeeping']],'Hoạt động'=>(int)$room['active']?'Đang sử dụng':'Ngừng sử dụng']); ?><div class="catalog-dialog-actions"><button type="button" class="button outline" data-close-dialog>Đóng</button></div><?php catalog_dialog_end(); ?>
        <?php catalog_dialog_start('room-edit-'.$roomId,'Cập nhật phòng '.$room['number'],$room['room_name'],post()&&input('action')==='update'&&(int)input('id')===$roomId&&$error!=='');catalog_error($error); ?>
        <form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'update','id'=>$roomId]); ?><p class="catalog-summary-line">Phòng <?= e($room['number']) ?> · <?= e($room['room_name']) ?></p><label>Tình trạng<select name="housekeeping"><?php foreach($roomStateLabels as $value=>$label): ?><option value="<?= e($value) ?>" <?= $room['housekeeping']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="checkbox"><input type="checkbox" name="active" value="1" <?= $room['active']?'checked':'' ?>>Cho phép sử dụng phòng</label><?php catalog_form_actions('Lưu thay đổi'); ?></form><?php catalog_dialog_end(); ?>
        <?php catalog_dialog_start('room-status-'.$roomId,$target?'Mở lại phòng':'Ngừng sử dụng phòng','Phòng '.$room['number'],false,true); ?><p><?= $target?'Đưa phòng trở lại danh mục hoạt động.':'Phòng sẽ ngừng nhận đặt mới. Những liên kết lưu trú cũ vẫn được giữ.' ?></p><form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'update','id'=>$roomId,'housekeeping'=>$room['housekeeping'],'active'=>$target]);catalog_form_actions($target?'Mở lại phòng':'Ngừng sử dụng',!$target); ?></form><?php catalog_dialog_end(); ?>
    <?php endforeach; ?>
    <?php catalog_dialog_start('room-create','Thêm phòng thực tế','Số phòng và loại phòng',post()&&input('action')==='add'&&$error!=='');catalog_error($error); ?>
    <form method="post"><?= csrf() ?><?php catalog_hidden(['action'=>'add']); ?><div class="form-grid"><label>Số phòng<input name="number" maxlength="20" value="<?= e(post()&&input('action')==='add'?input('number'):'') ?>" placeholder="Ví dụ: 101" required></label><label>Loại phòng<select name="room_type_id"><?php foreach($types as $type): ?><option value="<?= (int)$type['id'] ?>" <?= post()&&(int)input('room_type_id')===(int)$type['id']?'selected':'' ?>><?= e($type['name']) ?></option><?php endforeach; ?></select></label></div><?php catalog_form_actions('Thêm phòng'); ?></form><?php catalog_dialog_end(); ?>
</section><?php require __DIR__.'/../staff_footer.php'; ?>
